-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Globalisierung > Internationale Märkte
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Bieten internationale Märkte einem IT-Betrieb die Möglichkeit, neue Kunden zu gewinnen?', 2, '[{"text": "Ja", "correct": true, "because": "Internationale Märkte erweitern den Kundenstamm"}, {"text": "Nein", "correct": false, "because": "Neue Märkte bedeuten neue Kunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Erhöht der Zugang zu internationalen Märkten die Wettbewerbsintensität für einen IT-Betrieb?', 2, '[{"text": "Ja", "correct": true, "because": "Mehr Anbieter steigern den Wettbewerb"}, {"text": "Nein", "correct": false, "because": "Globaler Wettbewerb nimmt zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch internationale Märkte von Kostenvorteilen profitieren?', 2, '[{"text": "Ja", "correct": true, "because": "Zugang zu günstigeren Ressourcen möglich"}, {"text": "Nein", "correct": false, "because": "Kostenvorteile sind ein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind internationale Märkte für einen IT-Betrieb mit höheren Risiken verbunden?', 2, '[{"text": "Ja", "correct": true, "because": "Währungsrisiken und rechtliche Unterschiede"}, {"text": "Nein", "correct": false, "because": "Risiken steigen international"}]'),
('00000000-0000-0000-0000-000000000000', 'Ermöglichen internationale Märkte einem IT-Betrieb den Export von Software?', 2, '[{"text": "Ja", "correct": true, "because": "Software kann global verkauft werden"}, {"text": "Nein", "correct": false, "because": "Export ist ein Vorteil"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil internationaler Märkte für einen IT-Betrieb?', 2, '[{"text": "Erweiterung des Kundenstamms", "correct": true, "because": "Zugang zu neuen Kunden"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Kosten können sinken"}, {"text": "Weniger Wettbewerb", "correct": false, "because": "Wettbewerb steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung bringen internationale Märkte für einen IT-Betrieb?', 3, '[{"text": "Rechtliche Unterschiede", "correct": true, "because": "Länder haben unterschiedliche Vorschriften"}, {"text": "Geringere Nachfrage", "correct": false, "because": "Nachfrage kann steigen"}, {"text": "Einfacher Marktzugang", "correct": false, "because": "Zugang kann komplex sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erleichtert einem IT-Betrieb den Zugang zu internationalen Märkten?', 3, '[{"text": "Digitalisierung", "correct": true, "because": "Software kann online global verkauft werden"}, {"text": "Hohe Transportkosten", "correct": false, "because": "Wenig Einfluss bei IT"}, {"text": "Lokale Präsenz", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko entsteht einem IT-Betrieb durch internationale Märkte?', 2, '[{"text": "Währungsrisiken", "correct": true, "because": "Wechselkursänderungen beeinflussen Gewinne"}, {"text": "Geringere Qualität", "correct": false, "because": "Qualität nicht direkt betroffen"}, {"text": "Weniger Kunden", "correct": false, "because": "Kundenbasis wächst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil nutzt ein IT-Betrieb durch internationale Märkte?', 3, '[{"text": "Skaleneffekte durch größere Märkte", "correct": true, "because": "Größere Absatzmärkte senken Kosten"}, {"text": "Höhere lokale Steuern", "correct": false, "because": "Steuern variieren"}, {"text": "Weniger Innovation", "correct": false, "because": "Innovation wird gefördert"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten internationale Märkte einem IT-Betrieb?', 4, '[{"text": "Erweiterung des Kundenstamms", "correct": true, "because": "Neue Märkte, neue Kunden"}, {"text": "Kostenvorteile durch Skaleneffekte", "correct": true, "because": "Größere Produktion senkt Kosten"}, {"text": "Geringerer Wettbewerb", "correct": false, "because": "Wettbewerb steigt"}, {"text": "Zugang zu globalen Talenten", "correct": true, "because": "Internationale Arbeitskräfte nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen bringen internationale Märkte einem IT-Betrieb?', 3, '[{"text": "Währungsrisiken", "correct": true, "because": "Wechselkursänderungen"}, {"text": "Rechtliche Unterschiede", "correct": true, "because": "Länder haben eigene Gesetze"}, {"text": "Geringere Nachfrage", "correct": false, "because": "Nachfrage kann steigen"}, {"text": "Kulturelle Unterschiede", "correct": true, "because": "Kulturelle Anpassung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern den Erfolg eines IT-Betriebs auf internationalen Märkten?', 4, '[{"text": "Digitalisierung", "correct": true, "because": "Ermöglicht globalen Vertrieb"}, {"text": "Anpassung an lokale Bedürfnisse", "correct": true, "because": "Lokale Anpassung steigert Akzeptanz"}, {"text": "Hohe Transportkosten", "correct": false, "because": "Wenig Einfluss bei IT"}, {"text": "Exportfähigkeit von Software", "correct": true, "because": "Software ist leicht exportierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen einem IT-Betrieb durch internationale Märkte?', 3, '[{"text": "Währungsschwankungen", "correct": true, "because": "Beeinflussen Gewinne"}, {"text": "Politische Instabilität", "correct": true, "because": "Kann Märkte stören"}, {"text": "Geringere Produktionskosten", "correct": false, "because": "Das ist ein Vorteil"}, {"text": "Rechtliche Unsicherheiten", "correct": true, "because": "Unterschiedliche Gesetze"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet internationale Märkte von nationalen Märkten für einen IT-Betrieb?', 3, '[{"text": "Größere Kundenbasis", "correct": true, "because": "International mehr Kunden"}, {"text": "Höhere Risiken", "correct": true, "because": "Währung, Recht, Politik"}, {"text": "Weniger Wettbewerb", "correct": false, "because": "Wettbewerb steigt"}, {"text": "Zugang zu globalen Ressourcen", "correct": true, "because": "Internationale Märkte bieten mehr"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Internationale Märkte erweitern den Kundenstamm eines IT-Betriebs. b) Internationale Märkte reduzieren den Wettbewerb.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kundenstamm ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Internationale Märkte bieten Kostenvorteile durch Skaleneffekte. b) Internationale Märkte erhöhen Währungsrisiken.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Kostenvorteile und Währungsrisiken"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Internationale Märkte ermöglichen den Export von Software. b) Internationale Märkte sind frei von rechtlichen Unterschieden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Export ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Internationale Märkte erhöhen die Wettbewerbsintensität für einen IT-Betrieb. b) Internationale Märkte bieten keine Skaleneffekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wettbewerb ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Internationale Märkte bieten Zugang zu globalen Talenten. b) Internationale Märkte reduzieren die Nachfrage nach IT-Dienstleistungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Talente ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

